CREATE TABLE IF NOT EXISTS runtime_schema_migrations (version bigint PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT clock_timestamp(), checksum text NOT NULL);
CREATE TABLE IF NOT EXISTS runtime_deployments (deployment_id text PRIMARY KEY, provider text NOT NULL, runtime_class text NOT NULL, region text, architecture text NOT NULL, image_digest text NOT NULL, config_digest text NOT NULL, git_repository text, git_commit text, registered_at timestamptz NOT NULL DEFAULT clock_timestamp(), metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS runtime_work_orders (work_order text PRIMARY KEY, deployment_id text REFERENCES runtime_deployments(deployment_id), project text NOT NULL, launch jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE IF NOT EXISTS runtime_executions (execution_id text PRIMARY KEY, project text NOT NULL, work_order text REFERENCES runtime_work_orders(work_order), task text NOT NULL, model text NOT NULL, agent text NOT NULL, cwd text, wake_reason text NOT NULL, root_execution_id text NOT NULL, parent_execution_id text REFERENCES runtime_executions(execution_id), status text NOT NULL, attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0), recovery_attempts integer NOT NULL DEFAULT 0 CHECK (recovery_attempts >= 0), created_at timestamptz NOT NULL, started_at timestamptz, finished_at timestamptz, last_heartbeat_at timestamptz, requested_next_wake jsonb, failure jsonb, result jsonb, output jsonb, topology jsonb NOT NULL, model_runtime_telemetry jsonb, observer_state text NOT NULL DEFAULT 'not-eligible', observer_pending_at timestamptz, observer_observed_at timestamptz, runtime_metadata jsonb NOT NULL, version bigint NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS runtime_executions_due_recovery_idx ON runtime_executions(status,last_heartbeat_at);
CREATE TABLE IF NOT EXISTS runtime_attempts (execution_id text NOT NULL REFERENCES runtime_executions(execution_id), attempt integer NOT NULL CHECK (attempt >= 1), status text NOT NULL, started_at timestamptz NOT NULL, finished_at timestamptz, failure jsonb, process_result jsonb, output jsonb, result jsonb, PRIMARY KEY (execution_id,attempt));
CREATE TABLE IF NOT EXISTS runtime_leases (execution_id text PRIMARY KEY REFERENCES runtime_executions(execution_id), owner text NOT NULL, fence bigint NOT NULL, revision bigint NOT NULL, acquired_at timestamptz NOT NULL, heartbeat_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, released_at timestamptz);
CREATE TABLE IF NOT EXISTS runtime_schedules (schedule_key text PRIMARY KEY, schedule_id text NOT NULL UNIQUE, execution_id text NOT NULL UNIQUE, work_order text NOT NULL, project text NOT NULL, wake_time timestamptz NOT NULL, wake_reason text NOT NULL, priority text NOT NULL, launch jsonb NOT NULL, state text NOT NULL DEFAULT 'pending', claim_owner text, claim_fence bigint, claimed_at timestamptz, finished_at timestamptz, recovery_attempts integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS runtime_schedules_due_idx ON runtime_schedules(state,wake_time,priority,schedule_key);
CREATE TABLE IF NOT EXISTS runtime_events (event_id text PRIMARY KEY, execution_id text REFERENCES runtime_executions(execution_id), event_type text NOT NULL, occurred_at timestamptz NOT NULL, payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS runtime_model_telemetry (telemetry_id text PRIMARY KEY, execution_id text NOT NULL REFERENCES runtime_executions(execution_id), attempt integer, occurred_at timestamptz NOT NULL, payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS runtime_host_telemetry (telemetry_id text PRIMARY KEY, execution_id text, host_instance_id text NOT NULL, occurred_at timestamptz NOT NULL, availability text NOT NULL, payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS runtime_evidence (execution_id text NOT NULL REFERENCES runtime_executions(execution_id), evidence_id text NOT NULL, label text NOT NULL, object_key text NOT NULL, object_uri text NOT NULL, sha256 text NOT NULL, byte_count bigint NOT NULL, truncated boolean NOT NULL, content_type text NOT NULL, retention_class text NOT NULL, created_at timestamptz NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, PRIMARY KEY (execution_id,evidence_id), UNIQUE(object_key,sha256));
CREATE TABLE IF NOT EXISTS observer_digests (execution_id text PRIMARY KEY REFERENCES runtime_executions(execution_id), digest_schema text NOT NULL, observer_version text NOT NULL, digest jsonb NOT NULL, provenance_hash text NOT NULL, recorded_at timestamptz NOT NULL, lifecycle_state text NOT NULL);
CREATE TABLE IF NOT EXISTS observer_semantic_sidecars (execution_id text PRIMARY KEY REFERENCES observer_digests(execution_id), semantic_schema text NOT NULL, semantic jsonb NOT NULL, semantic_hash text NOT NULL, recorded_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS observer_lifecycle (lifecycle_id text PRIMARY KEY, execution_id text NOT NULL, from_state text NOT NULL, to_state text NOT NULL, status text NOT NULL, attempt integer, error_class text, reason text, retryable boolean, occurred_at timestamptz NOT NULL, payload jsonb NOT NULL);
